<?php
declare(strict_types=1);
session_start();
require_once __DIR__ . '/config/database.php';
require_once __DIR__ . '/config/audit.php';
if (!isset($_SESSION['user'])) { header('Location: login.php'); exit; }
$me=$_SESSION['user']; $role=$me['role_code']??'STAFF';
if (empty($_GET['download'])) audit_log($pdo, $me, 'page_view', 'documents.php');
$scopeSql=''; $scopeParams=[];
if ($role==='SUPERVISOR') { $scopeSql=' AND (t.assigned_department_id=? OR creator.department_id=?)'; $scopeParams=[(int)($me['department_id']??0),(int)($me['department_id']??0)]; }
elseif (!in_array($role,['ADMIN','DIRECTOR'],true)) { $scopeSql=' AND (t.created_by=? OR t.assigned_to=?)'; $scopeParams=[(int)$me['user_id'],(int)$me['user_id']]; }
$id=(int)($_GET['download']??0);
if ($id>0) {
    $stmt=$pdo->prepare('SELECT t.task_id,t.task_code,t.evidence_file FROM tasks t LEFT JOIN users creator ON creator.user_id=t.created_by WHERE t.task_id=?'.$scopeSql.' LIMIT 1');
    $stmt->execute(array_merge([$id],$scopeParams)); $doc=$stmt->fetch();
    if (!$doc || empty($doc['evidence_file']) || !preg_match('~^uploads/evidence/[a-f0-9]{40}\.(pdf|jpg|png|gif|doc|docx|xls|xlsx)$~', $doc['evidence_file'])) { http_response_code(404); exit('ไม่พบเอกสาร'); }
    $base=realpath(__DIR__.'/uploads/evidence'); $path=realpath(__DIR__.'/'.$doc['evidence_file']);
    if (!$base || !$path || !str_starts_with($path,$base.DIRECTORY_SEPARATOR) || !is_file($path)) { http_response_code(404); exit('ไม่พบเอกสาร'); }
    audit_log($pdo, $me, 'document_downloaded', 'documents.php', ['task_id' => $id]);
    $ext=strtolower(pathinfo($path,PATHINFO_EXTENSION)); $contentTypes=['pdf'=>'application/pdf','jpg'=>'image/jpeg','png'=>'image/png','gif'=>'image/gif','doc'=>'application/msword','docx'=>'application/vnd.openxmlformats-officedocument.wordprocessingml.document','xls'=>'application/vnd.ms-excel','xlsx'=>'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'];
    header('Content-Type: '.$contentTypes[$ext]); header('Content-Length: '.filesize($path)); header('Content-Disposition: attachment; filename="'.rawurlencode($doc['task_code'].'.'.$ext).'"'); header('X-Content-Type-Options: nosniff');
    readfile($path); exit;
}
$search=trim((string)($_GET['q']??'')); $from=trim((string)($_GET['from']??'')); $to=trim((string)($_GET['to']??''));
$where=' WHERE (t.evidence_file IS NOT NULL OR t.evidence_url IS NOT NULL)'.$scopeSql; $params=$scopeParams;
if ($search!=='') { $where.=' AND (t.title LIKE ? OR t.task_code LIKE ? OR creator.full_name LIKE ?)'; $q='%'.$search.'%'; array_push($params,$q,$q,$q); }
foreach(['from'=>'>=','to'=>'<='] as $key=>$op) { $value=${$key}; if ($value!=='' && preg_match('/^\d{4}-\d{2}-\d{2}$/',$value)) { $where.=' AND DATE(t.created_at) '.$op.' ?'; $params[]=$value; } }
$stmt=$pdo->prepare('SELECT t.task_id,t.task_code,t.title,t.category,t.status,t.created_at,t.evidence_file,t.evidence_url,creator.full_name AS creator_name,d.department_name FROM tasks t LEFT JOIN users creator ON creator.user_id=t.created_by LEFT JOIN departments d ON d.department_id=t.assigned_department_id'.$where.' ORDER BY t.created_at DESC');
$stmt->execute($params); $documents=$stmt->fetchAll();
$roleNames=['STAFF'=>'บุคลากร','SUPERVISOR'=>'หัวหน้างาน','DIRECTOR'=>'หัวหน้าสำนักงาน','ADMIN'=>'ผู้ดูแลระบบ'];
function docEsc(?string $s):string{return htmlspecialchars($s??'',ENT_QUOTES,'UTF-8');}
?>
