ter}.btn.light{background:#f1f0ec;color:#484a4d}.count{border-radius:20px;background:#fff0e3;color:#b95b17;padding:5px 9px;font-size:10px}.doclist{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:11px;padding:13px}.doc{border:1px solid #efeee9;border-radius:10px;padding:13px;display:grid;grid-template-columns:38px minmax(0,1fr);gap:10px;align-items:start}.fileicon{width:38px;height:42px;border-radius:9px;background:#fff0e3;color:#d66c20;display:grid;place-items:center;font:600 10px Kanit,sans-serif}.doctitle{font:500 13px Kanit,sans-serif;margin:0 0 3px;overflow-wrap:anywhere}.meta{font-size:10px;color:var(--muted);line-height:1.7}.docactions{display:flex;gap:6px;flex-wrap:wrap;margin-top:9px}.empty{text-align:center;padding:44px 20px;color:var(--muted)}.hint{text-align:center;color:#999;font-size:10px;margin-top:20px}
@media(max-width:850px){.shell{grid-template-columns:68px 1fr}.side{padding:15px 6px}.logo img{max-width:45px}.side .label{display:none}.side nav a{text-align:center;padding:11px 3px}.content{padding:17px}.doclist{grid-template-columns:1fr}}
@media(max-width:560px){.shell{grid-template-columns:1fr}.side{position:sticky;top:0;z-index:5;padding:5px 7px;border-right:0;border-bottom:1px solid var(--line)}.logo{display:none}.side nav{padding:0;display:flex;justify-content:space-around}.side nav a{padding:9px 6px}.top{height:52px;padding:0 12px}.content{padding:13px}.title h1{font-size:23px}.filters{grid-template-columns:1fr 1fr}.filters>div:first-child{grid-column:1/-1}}
</style><link rel="stylesheet" href="assets/css/app-theme.css?v=dark-interior-1"></head><body><div class="shell"><aside class="side"><div class="logo"><img src="assets/images/naresuan-logo.png" alt="มหาวิทยาลัยนเรศวร"></div><nav><a href="dashboard.php"><span class="ico">⌂</span><span class="label">Dashboard</span></a><a href="dashboard.php?section=create"><span class="ico">⊕</span><span class="label">บันทึกภาระงาน</span></a><a class="active" href="documents.php"><span class="ico">⇩</span><span class="label">ดาวน์โหลดเอกสาร</span></a><a href="dashboard.php?section=report"><span class="ico">▥</span><span class="label">รายงาน</span></a></nav></aside><main class="main"><header class="top"><div><strong>ระบบบริหารจัดการภาระงาน</strong><small>คลังเอกสารและหลักฐาน</small></div><div><strong><?=docEsc($me['full_name'])?></strong><small><?=docEsc($roleNames[$role]??$role)?></small></div></header><div class="content"><div class="title"><h1>ดาวน์โหลดเอกสาร</h1><p>ค้นหาไฟล์หลักฐานและลิงก์เอกสารจากรายการภาระงานที่คุณมีสิทธิ์เข้าถึง</p></div>
<section class="box"><div class="boxhead"><h2>ค้นหาเอกสาร</h2><a class="btn light" href="dashboard.php">กลับ Dashboard</a></div><div class="boxbody"><form class="filters" method="get"><div><label>ชื่อเอกสาร / ชื่องาน / รหัสงาน</label><input type="search" name="q" value="<?=docEsc($search)?>" placeholder="พิมพ์คำค้นหา"></div><div><label>ตั้งแต่วันที่</label><input type="date" name="from" value="<?=docEsc($from)?>"></div><div><label>ถึงวันที่</label><input type="date" name="to" value="<?=docEsc($to)?>"></div><button class="btn">ค้นหาเอกสาร</button></form></div></section>
<section class="box"><div class="boxhead"><div><h2>เอกสารแนบและหลักฐาน</h2><small style="color:#85888c">รายการตามสิทธิ์ของบัญชีคุณ</small></div><span class="count"><?=count($documents)?> รายการงาน</span></div><?php if(!$documents):?><div class="empty">ยังไม่มีเอกสารตรงกับคำค้นหา<br><small>ไฟล์และลิงก์หลักฐานจะปรากฏที่นี่เมื่อแนบมากับงาน</small></div><?php else:?><div class="doclist"><?php foreach($documents as $doc):?><article class="doc"><div class="fileicon"><?=$doc['evidence_file']?strtoupper(pathinfo($doc['evidence_file'],PATHINFO_EXTENSION)):'LINK'?></div><div><h3 class="doctitle"><?=docEsc($doc['title'])?></h3><div class="meta">รหัสงาน <?=docEsc($doc['task_code'])?> · <?=docEsc($doc['creator_name']??'ไม่ระบุผู้สร้าง')?><br><?=docEsc($doc['department_name']??'')?> · <?=docEsc(date('d/m/Y',strtotime($doc['created_at'])))?> · <?=$doc['category']==='special'?'งานกรณีพิเศษ':'งานหลัก'?></div><div class="docactions"><?php if($doc['evidence_file']):?><a class="btn" href="documents.php?download=<?=$doc['task_id']?>">ดาวน์โหลดไฟล์</a><?php endif;?><?php if($doc['evidence_url']):?><a class="btn light" href="<?=docEsc($doc['evidence_url'])?>" target="_blank" rel="noopener noreferrer">เปิดลิงก์หลักฐาน</a><?php endif;?></div></div></article><?php endforeach;?></div><?php endif;?></section><p class="hint">เอกสารส่วนนี้แสดงเฉพาะงานในขอบเขตสิทธิ์ของคุณ</p></div></main></div></body></html>
